def set_label(self, label, **kw):
    """Label the long axis of the colorbar."""
    if label is None or (isinstance(label, str) and label.lower() == "none"):
        self._label = ''
    else:
        self._label = str(label)

    self._labelkw = kw
    self._set_label()
